export const terms = {
  permission: 'An app-by-app choice that lets the app use a feature or data, such as the camera or location.',
  'Allow only while using the app': 'The app may use the camera only while it is open on screen.',
  'Privacy controls': 'Device-wide switches, such as Camera access, that block a feature for every app at once.',
  'Clear storage': "Deletes all of an app's data permanently, as if the app were newly installed.",
  'Allow background usage': 'The Android switch that lets an app use the battery while you are not using it. Optimized is the recommended choice.',
  Optimized: 'Android background battery mode that limits an app based on how you use it. Recommended for most apps.',
  Unrestricted: 'Android background battery mode with no limits. It may use more battery.',
  pairing: 'Two Bluetooth devices exchanging keys so they trust each other. A paired device can then connect without pairing again.',
  'discovery mode': 'A mode in which a Bluetooth accessory announces itself so a phone can find and pair with it. Also called pairing mode.',
  'Find Hub': 'The Google app and web page that locates, rings, locks (Mark as lost) or erases a lost Android device.',
  'Mark as lost': 'A Find Hub action that locks the phone and shows your message and contact info on its lock screen.',
  'toner cartridge': 'The laser printer supply that holds the toner powder. Faded pages are the classic sign it is running out.',
  'drum unit': 'The light-sensitive drum that carries the toner image to the paper. Lexmark calls it the imaging unit.',
  fuser: 'The heated part that melts toner into the paper. Toner that rubs off points to the fuser or a wrong paper type setting.',
  'maintenance kit': 'A set of parts that wear by page count, such as the fuser and the pick and transfer rollers, replaced together on schedule.',
  'pick-up roller': 'The rubber roller that pulls one sheet at a time from the tray. Dust on it or on the separator pad causes misfeeds.',
  'separator pad': 'A pad in the paper tray that holds back all but the top sheet so only one sheet feeds.',
  PCL: 'Printer Command Language, a page description language that many laser printers understand.',
  PostScript: 'A page description language from Adobe. A printer that does not support it cannot print PostScript jobs correctly.',
};

